sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	var defaultSysId = '40cfcb08c34792107527961d0501311c';
	var IndSysId = 'cf406b42c36312107527961d05013126';
	var grMapType = new GlideRecord('cmdb_rel_type');
	grMapType.addQuery('sys_name', 'Depends on::Used by');
	grMapType.query();
	grMapType.next();
	var mapTypeSysId = grMapType.sys_id;
	var cid = current.applies_to.x_631631_grc_contr_common_id;
	var gaCiMap = new GlideAggregate('cmdb_rel_ci');
	gaCiMap.addAggregate('COUNT');
	gaCiMap.addQuery('parent', current.applies_to);
	gaCiMap.addQuery('type', mapTypeSysId);
	gaCiMap.query();
	gaCiMap.next();
	var childCount = gaCiMap.getAggregate('COUNT');

	var setEntTypeId = defaultSysId;

	var grIndDevCount = new GlideRecord('x_631631_sc_grc_co_san_results');
	grIndDevCount.addQuery('common_id', cid);
	grIndDevCount.query();
	if(grIndDevCount.hasNext()) {
		grIndDevCount.next();
		if (grIndDevCount.ci_count == childCount) {
			setEntTypeId = IndSysId;
		}
	}
	var grEntType = new GlideRecord('sn_grc_m2m_profile_profile_type');
	grEntType.initialize();
	grEntType.profile = current.sys_id;
	grEntType.profile_type = setEntTypeId;
	var newId = grEntType.insert();

})(current, previous);
